function stBuild(arr){
  if(!Array.isArray(arr)||!arr.length) return { value:null, error:'数组为空' };
  for(var i=0;i<arr.length;i++){
    if(typeof arr[i]!=='number'||!isFinite(arr[i])) return { value:null, error:'第 '+(i+1)+' 项不是有限数' };
  }
  var n=arr.length;
  var t={ n:n, sum:new Array(4*n).fill(0), min:new Array(4*n).fill(0),
          max:new Array(4*n).fill(0), lazy:new Array(4*n).fill(0) };
  (function build(node,l,r){
    if(l===r){ t.sum[node]=arr[l]; t.min[node]=arr[l]; t.max[node]=arr[l]; return; }
    var mid=(l+r)>>1;
    build(2*node,l,mid); build(2*node+1,mid+1,r);
    t.sum[node]=t.sum[2*node]+t.sum[2*node+1];
    t.min[node]=Math.min(t.min[2*node],t.min[2*node+1]);
    t.max[node]=Math.max(t.max[2*node],t.max[2*node+1]);
  })(1,0,n-1);
  return { value:t, error:null };
}
function stPush(t,node,l,r){
  if(t.lazy[node]===0) return;
  var mid=(l+r)>>1, d=t.lazy[node];
  var kids=[[2*node,l,mid],[2*node+1,mid+1,r]];
  for(var i=0;i<2;i++){
    var k=kids[i][0], kl=kids[i][1], kr=kids[i][2];
    t.sum[k]+=d*(kr-kl+1); t.min[k]+=d; t.max[k]+=d; t.lazy[k]+=d;
  }
  t.lazy[node]=0;
}
function stUpdate(t,ql,qr,delta){
  if(ql<0||qr>=t.n||ql>qr) return { value:null, error:'区间 ['+ql+','+qr+'] 越界（0..'+(t.n-1)+'）' };
  (function upd(node,l,r){
    if(qr<l||r<ql) return;
    if(ql<=l&&r<=qr){
      t.sum[node]+=delta*(r-l+1); t.min[node]+=delta; t.max[node]+=delta; t.lazy[node]+=delta;
      return;
    }
    stPush(t,node,l,r);
    var mid=(l+r)>>1;
    upd(2*node,l,mid); upd(2*node+1,mid+1,r);
    t.sum[node]=t.sum[2*node]+t.sum[2*node+1];
    t.min[node]=Math.min(t.min[2*node],t.min[2*node+1]);
    t.max[node]=Math.max(t.max[2*node],t.max[2*node+1]);
  })(1,0,t.n-1);
  return { value:true, error:null };
}
function stQuery(t,ql,qr,kind){
  if(ql<0||qr>=t.n||ql>qr) return { value:null, error:'区间 ['+ql+','+qr+'] 越界（0..'+(t.n-1)+'）' };
  var k=kind||'sum';
  if(k!=='sum'&&k!=='min'&&k!=='max') return { value:null, error:'kind 必须是 sum/min/max' };
  var res=(function q(node,l,r){
    if(qr<l||r<ql) return null;
    if(ql<=l&&r<=qr) return t[k][node];
    stPush(t,node,l,r);
    var mid=(l+r)>>1;
    var a=q(2*node,l,mid), b=q(2*node+1,mid+1,r);
    if(a===null) return b; if(b===null) return a;
    if(k==='sum') return a+b;
    if(k==='min') return Math.min(a,b);
    return Math.max(a,b);
  })(1,0,t.n-1);
  return { value:res, error:null };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { stBuild:stBuild, stUpdate:stUpdate, stQuery:stQuery };
}
if (typeof window !== 'undefined') {
  window.SegmentForgePure = { stBuild:stBuild, stUpdate:stUpdate, stQuery:stQuery };
}
